"""Convert the meeting corpus (json/txt/docx) to normalized transcript files.

Output per transcript (deduped by content hash):
  work/transcripts/<tid>.txt   lines: "Speaker 0: text ||t=00:00-00:01||" or "||#42||"
  work/manifest.json           tid -> {source, format, n_turns, speakers}
Turn text is flattened to one line. No content is altered.
"""
import json, re, zipfile, hashlib, os, sys, glob

M = "/Users/venkatgullapalli/My_AI_Lab/new-projects/my-os/content/inbox/ingestion-v2/business-context/meetings"
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "work", "transcripts")
os.makedirs(OUT, exist_ok=True)

def tidify(name):
    base = re.sub(r"\.(json|txt|docx)$", "", name)
    base = re.sub(r"[^A-Za-z0-9_-]+", "_", base).strip("_")
    return base[:80]

def one_line(s):
    return re.sub(r"\s+", " ", s).strip()

def parse_json(path):
    data = json.load(open(path, encoding="utf-8", errors="replace"))
    turns = []
    for i, e in enumerate(data):
        if isinstance(e, dict) and e.get("text"):
            turns.append((e.get("speaker", "Unknown"), one_line(e["text"]), f"#{i}"))
    return turns

def parse_txt(path):
    raw = open(path, encoding="utf-8", errors="replace").read()
    # blocks: "Speaker 0: \n00:00-00:01\ntext..." separated by blank lines
    turns = []
    for block in re.split(r"\n\s*\n", raw):
        m = re.match(r"\s*(Speaker \d+|[A-Za-z][\w .\-]{0,30}?):\s*\n(\d[\d:.\-]*)\n(.+)", block, re.S)
        if m:
            turns.append((m.group(1), one_line(m.group(3)), m.group(2)))
        else:
            m2 = re.match(r"\s*(Speaker \d+|[A-Za-z][\w .\-]{0,30}?):\s*(.+)", block, re.S)
            if m2 and m2.group(2).strip():
                turns.append((m2.group(1), one_line(m2.group(2)), "?"))
    return turns

def parse_docx(path):
    z = zipfile.ZipFile(path)
    xml = z.read("word/document.xml").decode("utf-8", "replace")
    xml = re.sub(r"<w:p[ >]", "\n<w:p ", xml)
    text = re.sub(r"<[^>]+>", "", xml)
    text = text.replace("&apos;", "'").replace("&quot;", '"').replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">")
    turns = []
    for line in text.split("\n"):
        line = line.strip()
        # "00:15Venkat G.Yes." or "1:02:15Keri S.text"
        m = re.match(r"^(\d{1,2}:\d{2}(?::\d{2})?)((?:[A-Z][A-Za-z'\-]+ )+[A-Z]\.)(.*)$", line)
        if m and m.group(3).strip():
            turns.append((m.group(2).strip().rstrip("."), one_line(m.group(3)), m.group(1)))
    return turns

manifest, seen = {}, {}
files = sorted(os.listdir(M))
skipped = []
for name in files:
    if name.endswith(".metadata.json") or name.startswith("."):
        continue
    path = os.path.join(M, name)
    try:
        if name.endswith(".json"):
            turns = parse_json(path)
        elif name.endswith(".txt"):
            turns = parse_txt(path)
        elif name.endswith(".docx"):
            turns = parse_docx(path)
        else:
            continue
    except Exception as e:
        skipped.append((name, f"parse error: {e}")); continue
    if len(turns) < 4:
        skipped.append((name, f"only {len(turns)} turns parsed")); continue
    h = hashlib.sha1("\x1f".join(s + "\x1e" + t for s, t, _ in turns).encode()).hexdigest()
    if h in seen:
        skipped.append((name, f"duplicate of {seen[h]}")); continue
    tid = tidify(name)
    seen[h] = name
    with open(os.path.join(OUT, tid + ".txt"), "w", encoding="utf-8") as f:
        for spk, txt, ts in turns:
            f.write(f"{spk}: {txt} ||t={ts}||\n")
    manifest[tid] = {"source": name, "format": name.rsplit(".", 1)[-1],
                     "n_turns": len(turns), "speakers": sorted({s for s, _, _ in turns})}

json.dump({"transcripts": manifest, "skipped": skipped},
          open(os.path.join(OUT, "..", "manifest.json"), "w"), indent=1)
print(f"converted {len(manifest)} unique transcripts; skipped {len(skipped)}")
for n, why in skipped:
    print("  SKIP", n, "--", why)

